import { useEffect, useMemo, useState } from 'react';
import { api, auth, invitesClient } from './client';
import {
  LayoutDashboard, RadioTower, UsersRound, MessagesSquare, Columns3, GitBranch, CalendarDays,
  Bot, BookOpenText, BrainCircuit, ChartNoAxesCombined, Wallet, Cable, UserRoundCog,
  Settings2, ChevronsUpDown, ChevronRight, Menu, X, Plus, Search, Bell, ArrowUpRight,
  ArrowRight, BadgeCheck, PhoneCall, MessageCircle, ShieldCheck, CircleHelp, Sparkles,
  Activity, Clock3, Check, Pause, Play, FileUp, FileDown, CheckCircle2, CircleAlert,
  Moon, Sun, LogOut, Send, ClipboardList, Building2, Target, CreditCard, Coins,
  LockKeyhole, CalendarCheck2, Ban, FileText, ExternalLink, Copy, 
  RefreshCcw, GripVertical, ListChecks, CalendarClock, CircleDot, Pencil,
  LoaderCircle, Eye, TrendingUp
} from 'lucide-react';
import './salesos.css';

type R = Record<string, any>;
type Data = Record<string, any>;
const cols = ['Novo Lead','Validado','Em Prospecção','Contato Realizado','Interação Iniciada','Interesse Identificado','Lead Qualificado','Reunião Agendada','Proposta Enviada','Negociação','Convertido','Perdido'];
const groups = [
  { name:'OPERAÇÃO', links:[
    {id:'overview',label:'Visão Geral',icon:LayoutDashboard},
    {id:'operations',label:'Central de Operações',icon:RadioTower},
    {id:'contacts',label:'Contatos & Empresas',icon:UsersRound},
    {id:'inbox',label:'Conversas 360°',icon:MessagesSquare},
    {id:'pipeline',label:'Pipeline Comercial',icon:Columns3},
    {id:'campaigns',label:'Cadências & Campanhas',icon:GitBranch},
    {id:'calendar',label:'Agenda Inteligente',icon:CalendarDays}
  ]},
  { name:'INTELIGÊNCIA', links:[
    {id:'agents',label:'Agentes de IA',icon:Bot},
    {id:'knowledge',label:'Base de Conhecimento',icon:BookOpenText},
    {id:'intelligence',label:'Inteligência Comercial',icon:BrainCircuit},
    {id:'reports',label:'Relatórios & Performance',icon:ChartNoAxesCombined}
  ]},
  { name:'GESTÃO', links:[
    {id:'wallet',label:'Carteira & Recargas',icon:Wallet},
    {id:'integrations',label:'Integrações',icon:Cable},
    {id:'team',label:'Equipe & Permissões',icon:UserRoundCog},
    {id:'settings',label:'Configurações',icon:Settings2}
  ]}
];
const labels:R={email:'E-mail',whatsapp:'WhatsApp',voice:'Ligação IA',internal:'Nota interna'};
const fmtNum=(n:number)=>new Intl.NumberFormat('pt-BR').format(n);
const money=(v:number)=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(v);
const date=(s:string)=>s?new Date(s).toLocaleDateString('pt-BR'):'—';
const datetime=(s:string)=>s?new Date(s).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'}):'—';
const dateLocal=(d:Date)=>new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);
const getErr=(e:unknown)=>{
  const obj=e as {response?:{data?:{message?:string;error?:string}},message?:string};
  return obj?.response?.data?.message||obj?.response?.data?.error||obj?.message||'Não foi possível concluir. Verifique os dados.';
};
const first=(s:string)=>s?.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase()||'—';
const allMenu=groups.flatMap(g=>g.links);
function Kpi({icon:Icon,label,value,foot,tone='blue'}:{icon:any,label:string,value:string,foot:string,tone?:string}){
  return <div className="sos-kpi"><div className="sos-kpi-top"><span>{label}</span><span className={'sos-icon '+tone}><Icon size={17}/></span></div><strong>{value}</strong><small>{foot}</small></div>;
}
function Placeholder({icon:Icon,title,description,action}:{icon:any,title:string,description:string,action?:React.ReactNode}){
  return <div className="sos-empty"><span><Icon size={25} strokeWidth={1.5}/></span><h3>{title}</h3><p>{description}</p>{action}</div>;
}
function Field({title,children,hint}:{title:string,children:React.ReactNode,hint?:string}){
  return <label className="sos-field"><span>{title}</span>{children}{hint&&<small>{hint}</small>}</label>;
}
function Status({value}:{value:string}){return <span className={'sos-status '+(['active','confirmed','delivered','read','Convertido','Concluído','agendado'].includes(value)?'good':['paused','pending','draft','Pendente','initiating'].includes(value)?'neutral':['bloqueado','failed','Perdido','uncertain'].includes(value)?'bad':'info')}>{({active:'Ativa',draft:'Rascunho',paused:'Pausada',pending:'Pendente',confirmed:'Confirmado',agendado:'Agendado',uncertain:'Verificação pendente'} as R)[value]||value||'Novo'}</span>;}
function Modal({title,onClose,children,footer}:{title:string,onClose:()=>void,children:React.ReactNode,footer?:React.ReactNode}){
  return <div className="sos-dialog-shade" onMouseDown={e=>{if(e.currentTarget===e.target)onClose();}}><div className="sos-dialog"><div className="sos-dialog-head"><div><small>R2R SALESOS / NOVO REGISTRO</small><h2>{title}</h2></div><button className="sos-iconbtn" onClick={onClose}><X size={19}/></button></div><div className="sos-dialog-body">{children}</div>{footer&&<div className="sos-dialog-foot">{footer}</div>}</div></div>;
}
function App(){
  const [account,setAccount]=useState<R|null>(null),[booting,setBooting]=useState(true);
  const [data,setData]=useState<Data>({}),[wid,setWid]=useState('');
  const [page,setPage]=useState('overview'),[theme,setTheme]=useState<'dark'|'light'>('dark');
  const [collapsed,setCollapsed]=useState(false),[mobile,setMobile]=useState(false);
  const [search,setSearch]=useState(''),[modal,setModal]=useState(''),[form,setForm]=useState<R>({});
  const [busy,setBusy]=useState(false),[notice,setNotice]=useState(''),[selectedLead,setSelectedLead]=useState('');
  const [inviteCode,setInviteCode]=useState(''),[inviteLink,setInviteLink]=useState(''),[draft,setDraft]=useState('');
  const [integrations,setIntegrations]=useState<R[]>([]),[calendarMode,setCalendarMode]=useState<'day'|'week'|'month'>('week');
  const [calendarAt,setCalendarAt]=useState(new Date());
  const [reportPeriod,setReportPeriod]=useState('30');
  const show=(msg:string)=>setNotice(msg);
  const reload=async()=>{
    const response=await api.get('/api/salesos/bootstrap');
    const b=response.data as Data;
    setData(b);
    setWid(current=>b.workspaces?.some((w:R)=>w.id===current)?current:(b.workspaces?.[0]?.id||''));
  };
  useEffect(()=>{
    let alive=true;
    const start=async()=>{try{
      const code=invitesClient.getPendingCode();if(code)setInviteCode(code);
      const u=await auth.getUser();if(!alive)return;setAccount(u);
      if(u)await reload();
    }catch(e){if(alive)show(getErr(e));}finally{if(alive)setBooting(false);}};
    void start();return()=>{alive=false;};
  },[]);
  const workspaces:R[]=data.workspaces||[];
  const ws=workspaces.find(w=>w.id===wid);
  const filtered=(kind:string)=>((data[kind]||[]) as R[]).filter(r=>r.workspaceId===wid);
  const leads=filtered('leads');
  const campaigns=filtered('campaigns');
  const messages=filtered('messages').sort((a,b)=>String(a.at).localeCompare(String(b.at)));
  const activity=filtered('activity').sort((a,b)=>String(b.at).localeCompare(String(a.at)));
  const appointments=filtered('appointments').filter(a=>a.status!=='cancelado').sort((a,b)=>String(a.startAt).localeCompare(String(b.startAt)));
  const opportunities=filtered('opportunities');
  const wallet=filtered('wallet')[0]||{balanceCents:0,reservedCents:0};
  const ledger=filtered('ledger');
  const topups=filtered('topups');
  const role=ws?.role||'viewer',editable=['owner','admin','editor'].includes(role),admin=['owner','admin'].includes(role);
  const select=(p:string)=>{setPage(p);setMobile(false);setSearch('');};
  const filteredLeads=leads.filter(l=>([l.name,l.company,l.email,l.phone,l.status].join(' ')).toLowerCase().includes(search.toLowerCase()));
  const stats=useMemo(()=>{
    const recent=Number(reportPeriod)*86400000,cutoff=Date.now()-recent;
    const events=messages.filter(m=>Date.parse(m.at||m.createdAt||'')>=cutoff&&m.channel!=='internal');
    return {
      total:leads.length,valid:leads.filter(l=>!l.optOut&&l.legalBasis&&l.source).length,
      qualified:leads.filter(l=>['Lead Qualificado','Reunião Agendada','Proposta Enviada','Negociação','Convertido'].includes(l.stage||l.status)).length,
      booked:appointments.length,active:campaigns.filter(c=>c.status==='active').length,
      inbound:events.filter(e=>e.direction==='inbound'||e.status==='replied').length,
      delivered:events.filter(e=>['delivered','read'].includes(e.status)).length,
      calls:events.filter(e=>e.channel==='voice'&&['call_started','call_answered','call_ended'].includes(e.status)).length,
      cost:events.reduce((sum,e)=>sum+(Number(e.costCents)||0),0)/100,
      initiated:activity.filter(a=>a.kind==='dispatch').length,
      converted:leads.filter(l=>(l.stage||l.status)==='Convertido').length
    };
  },[leads,appointments,messages,campaigns,activity,reportPeriod]);
  const sync=async()=>{try{await reload();show('Informações atualizadas.');}catch(e){show(getErr(e));}};
  const submit=async(url:string,b:R,method:'post'|'put'='post')=>{
    setBusy(true);
    try {
      const r=method==='post'?await api.post(url,b):await api.put(url,b);
      await reload();setModal('');setForm({});show('Alterações registradas com sucesso.');
      return r.data as R;
    }catch(e){show(getErr(e));return null;}finally{setBusy(false);}
  };
  const open=(m:string,defaults:R={})=>{setModal(m);setForm(m==='meeting'?{startLocal:dateLocal(new Date(Date.now()+86400000)),duration:60,...defaults}:defaults);setDraft('');setInviteLink('');};
  const f=(key:string,value:any)=>setForm(old=>({...old,[key]:value}));
  const ensure=()=>{if(!ws)show('Crie uma empresa antes de usar este módulo.');};
  const handleForm=async()=>{
    if(modal==='company')await submit('/api/workspaces',{name:form.name,niche:form.niche,description:form.description});
    if(modal==='lead')await submit('/api/salesos/leads',{...form,workspaceId:wid});
    if(modal==='agentEdit')await submit('/api/salesos/records/agents/'+form.id,{...form,workspaceId:wid},'put');
    if(modal==='campaign')await submit('/api/salesos/campaigns',{...form,workspaceId:wid});
    if(['agent','knowledge','task','opportunity','cadence'].includes(modal)){
      const m:R={agent:'agents',knowledge:'knowledge',task:'tasks',opportunity:'opportunities',cadence:'cadences'};
      await submit('/api/salesos/records/'+m[modal],{...form,workspaceId:wid,...(modal==='cadence'?{steps:String(form.stepsText||'').split('\n').filter(Boolean).map((v:string,i:number)=>({order:i+1,instruction:v}))}:{})});
    }
    if(modal==='meeting'){
      if(!form.startLocal){show('Escolha data e hora.');return;}
      const value=new Date(form.startLocal);
      if(Number.isNaN(value.getTime())){show('Data e hora inválidas.');return;}
      await submit('/api/salesos/records/appointments',{...form,workspaceId:wid,startAt:value.toISOString()});
    }
    if(modal==='note')await submit('/api/salesos/notes',{workspaceId:wid,leadId:selectedLead,message:form.message});
    if(modal==='invite'){
      setBusy(true);try{
        const r=await api.post('/api/salesos/team/invite',{workspaceId:wid,email:form.email,role:form.role});
        const url=invitesClient.buildJoinUrl(r.data.code,{path:'#/join'});
        setInviteLink(url);await reload();
      }catch(e){show(getErr(e));}finally{setBusy(false);}
    }
    if(modal==='topup'){
      if(!window.confirm('Gerar cobrança apenas no SANDBOX do Asaas? Não haverá créditos de produção.'))return;
      setBusy(true);try{
        const requestId=crypto.randomUUID();
        const r=await api.post('/api/salesos/wallet/topup',{workspaceId:wid,amount:Number(form.amount),requestId});
        if(r.data.url)window.open(r.data.url,'_blank','noopener,noreferrer');
        await reload();setModal('');show('Cobrança de TESTE criada. Saldo só muda após webhook confirmado no sandbox.');
      }catch(e){show(getErr(e));}finally{setBusy(false);}
    }
  };
  const cancelMeeting=async(a:R)=>{
    if(!window.confirm('Cancelar o compromisso e liberar o horário?'))return;
    await submit('/api/salesos/appointments/'+a.id+'/cancel',{workspaceId:wid});
  };
  const testIntegration=async(key:string)=>{
    if(!ws)return;
    setBusy(true);
    try{const r=await api.post('/api/salesos/integrations/'+key+'/test',{workspaceId:wid});show('Autenticação '+key+' testada em '+datetime(r.data.validatedAt)+'. Isso não habilita envios.');}
    catch(e){show(getErr(e));}finally{setBusy(false);}
  };
  const changeStage=async(lead:R,stage:string)=>{
    await submit('/api/salesos/leads/'+lead.id,{workspaceId:wid,stage},'put');
  };
  const blockLead=async(lead:R)=>{
    if(!window.confirm('Bloquear este contato para todos os canais desta operação?'))return;
    await submit('/api/salesos/leads/'+lead.id,{workspaceId:wid,optOut:true},'put');
  };
  const uploadCsv=async(file:File)=>{
    if(file.size>1024*1024){show('Divida o arquivo em partes de até 1 MB.');return;}
    const text=await file.text();const delim=text.split('\n')[0]?.includes(';')?';':',';
    const rows=text.trim().split(/\r?\n/),heads=(rows.shift()||'').split(delim).map(t=>t.trim().toLowerCase());
    const map:R={nome:'name',empresa:'company',telefone:'phone',celular:'phone',origem:'source',baselegal:'legalBasis',whatsappoptin:'whatsappOptIn',voiceallowed:'voiceAllowed'};
    const items=rows.filter(Boolean).map(line=>{
      const cells=line.split(delim),r:R={};
      heads.forEach((h,i)=>{const k=map[h.replace(/[^a-z]/g,'')]||h;r[k]=cells[i]?.replace(/^"|"$/g,'').trim()||'';});
      r.whatsappOptIn=['true','1','sim'].includes(String(r.whatsappOptIn).toLowerCase());
      r.voiceAllowed=['true','1','sim'].includes(String(r.voiceAllowed).toLowerCase());
      return r;
    });
    setBusy(true);let created=0,duplicates=0,invalid=0;
    try{
      for(let i=0;i<items.length;i+=100){
        const r=await api.post('/api/salesos/leads',{workspaceId:wid,items:items.slice(i,i+100)});
        created+=r.data.created;duplicates+=r.data.duplicate;invalid+=r.data.invalid;
      }
      await reload();show('Importação: '+created+' criados, '+duplicates+' duplicados, '+invalid+' inválidos.');
    }catch(e){show(getErr(e));}finally{setBusy(false);}
  };
  const exportCsv=()=>{
    const keys=['name','company','email','phone','source','legalBasis','status'];
    const q=(v:unknown)=>'"'+String(v??'').replace(/"/g,'""')+'"';
    const csv=[keys.join(';'),...filteredLeads.map(r=>keys.map(k=>q(r[k])).join(';'))].join('\n');
    const a=document.createElement('a');const u=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'}));a.href=u;a.download='r2r-salesos-contatos.csv';a.click();URL.revokeObjectURL(u);
  };
  const fileUpload=async(file:File)=>{
    if(file.size>400000){show('Tamanho máximo de arquivo: 400 KB.');return;}
    const data64=await new Promise<string>((resolve,reject)=>{
      const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]||'');reader.onerror=()=>reject(new Error('Falha de leitura'));reader.readAsDataURL(file);
    });
    await submit('/api/salesos/knowledge/upload',{workspaceId:wid,filename:file.name,mime:file.type||'text/plain',data:data64});
  };
  const showFile=async(item:R)=>{
    try{const r=await api.get('/api/salesos/knowledge/'+item.id+'/url?workspaceId='+encodeURIComponent(wid));if(r.data.url)window.open(r.data.url,'_blank','noopener,noreferrer');}
    catch(e){show(getErr(e));}
  };
  const stopCampaign=async(c:R,action:'pause'|'activate')=>{
    if(!window.confirm(action==='activate'?'Você confirma a ativação desta campanha após homologação legal e técnica?':'Pausar imediatamente esta campanha?'))return;
    await submit('/api/salesos/campaigns/'+c.id+'/action',{workspaceId:wid,action,confirmed:true});
  };
  const makeDraft=async()=>{
    if(!ws){ensure();return;}
    setBusy(true);
    try{
      const r=await api.post('/api/salesos/ai/draft',{workspaceId:wid,channel:form.channel||'email',objective:form.objective||'',offer:form.offer||''});
      setDraft(r.data.text);show('Rascunho gerado para revisão humana.');
    }catch(e){show(getErr(e));}finally{setBusy(false);}
  };
  if(booting)return <div className="sos-loading"><LoaderCircle className="sos-spin" size={25}/><b>R2R SalesOS</b><span>Restaurando seu ambiente seguro...</span></div>;
  if(!account)return <div className="sos-auth"><div className="sos-auth-left"><div className="sos-logo"><span>R<span>2</span></span> R2R <b>SalesOS</b></div><span className="sos-auth-eyebrow">COMERCIAL INTELLIGENCE PLATFORM</span><h1>Seu crescimento.<br/>Uma única operação.</h1><p>Contatos, conversas, campanhas, inteligência artificial e resultados em uma plataforma comercial personalizada.</p><button className="sos-btn primary large" onClick={()=>auth.signInWithRedirect().catch(e=>show(getErr(e)))}>Acessar minha plataforma <ArrowUpRight size={17}/></button><small><ShieldCheck size={14}/> Ambiente com autenticação segura e dados por operação</small></div><div className="sos-auth-right"><div className="sos-auth-screen"><div className="sos-auth-overline">CENTRAL DE OPERAÇÕES</div><h2>Conquiste com inteligência.</h2><div className="sos-auth-lines"><span/><span/><span/><span/></div><div className="sos-auth-metrics"><div><Target/><span>Prospecção</span></div><div><MessagesSquare/><span>Relacionamento</span></div><div><ChartNoAxesCombined/><span>Performance</span></div></div></div></div>{notice&&<div className="sos-toast" onClick={()=>setNotice('')}>{notice} <X size={15}/></div>}</div>;
  if(inviteCode)return <div className="sos-invite"><div className="sos-invite-card"><Building2 size={31}/><h1>Convite para uma operação</h1><p>Você recebeu acesso a um ambiente de trabalho comercial. Sua associação exige autenticação e permissões determinadas pelo proprietário.</p><button className="sos-btn primary" disabled={busy} onClick={async()=>{setBusy(true);try{await api.post('/api/salesos/team/join',{code:inviteCode});invitesClient.clearPendingCode();setInviteCode('');await reload();show('Convite aceito.');}catch(e){show(getErr(e));}finally{setBusy(false);}}}>Aceitar convite <ArrowRight size={16}/></button><button className="sos-btn muted" onClick={()=>{invitesClient.clearPendingCode();setInviteCode('');}}>Agora não</button>{notice&&<p>{notice}</p>}</div></div>;
  const title=allMenu.find(l=>l.id===page)?.label||'Visão Geral';
  const actions = page==='contacts'?[{name:'Exportar',icon:FileDown,act:exportCsv,secondary:true},{name:'Novo contato',icon:Plus,act:()=>open('lead')}]:page==='campaigns'?[{name:'Nova campanha',icon:Plus,act:()=>open('campaign')}]:page==='calendar'?[{name:'Nova tarefa',icon:ClipboardList,act:()=>open('task')},{name:'Agendar compromisso',icon:Plus,act:()=>open('meeting')}]:page==='agents'?[{name:'Criar agente',icon:Plus,act:()=>open('agent')}]:page==='knowledge'?[{name:'Adicionar conhecimento',icon:Plus,act:()=>open('knowledge')}]:page==='pipeline'?[{name:'Nova oportunidade',icon:Plus,act:()=>open('opportunity')}]:page==='team'?[{name:'Convidar membro',icon:Plus,act:()=>open('invite')}]:[];
  return <div className={'sos-app '+theme+(collapsed?' collapsed':'')}>
    {mobile&&<div className="sos-mobile-shade" onClick={()=>setMobile(false)}/>}
    <aside className={'sos-sidebar '+(mobile?'mobile-on':'')}>
      <button className="sos-logo" onClick={()=>select('overview')}><span>R<span>2</span></span><span className="sos-brand-label">R2R <b>SalesOS</b><small>COMMERCIAL INTELLIGENCE</small></span></button>
      <div className="sos-org"><div className="sos-org-avatar"><Building2 size={16}/></div><div><strong>{ws?.name||'Nenhuma empresa'}</strong><small>{ws?.niche||'Configuração inicial'}</small></div><button title="Trocar empresa" onClick={()=>{document.getElementById('sos-workspace')?.focus();}}><ChevronsUpDown size={15}/></button></div>
      <div className="sos-side-scroll">{groups.map(g=><div className="sos-nav-group" key={g.name}><div className="sos-group-label">{g.name}</div>{g.links.map(l=><button key={l.id} title={l.label} className={'sos-nav-link '+(page===l.id?'current':'')} onClick={()=>select(l.id)}><l.icon size={17} strokeWidth={1.8}/><span>{l.label}</span>{l.id==='campaigns'&&stats.active>0&&<em>{stats.active}</em>}</button>)}</div>)}</div>
      <div className="sos-side-foot"><div className="sos-protect"><ShieldCheck size={16}/><span>Operação protegida<small>Controles de elegibilidade ativos</small></span></div><div className="sos-user"><div className="sos-user-circle">{first(account.name||account.email||'Usuário')}</div><span><b>{account.name||'Usuário autenticado'}</b><small>{account.email||role}</small></span><button className="sos-iconbtn" title="Sair" onClick={()=>auth.signOut().then(()=>setAccount(null))}><LogOut size={16}/></button></div></div>
    </aside>
    <div className="sos-content">
      <header className="sos-topbar"><div className="sos-top-left"><button className="sos-iconbtn sos-mobile-button" onClick={()=>setMobile(!mobile)}><Menu size={19}/></button><button className="sos-iconbtn sos-collapse-button" onClick={()=>setCollapsed(!collapsed)} title="Recolher menu"><Menu size={18}/></button><span className="sos-breadcrumb">Workspace</span><ChevronRight size={14}/><b>{title}</b></div><div className="sos-top-right"><div className="sos-global-search"><Search size={16}/><input placeholder="Buscar contatos..." value={search} onChange={e=>setSearch(e.target.value)}/><kbd>⌘ K</kbd></div><button className="sos-iconbtn" title="Atualizar" onClick={sync}><RefreshCcw size={17}/></button><button className="sos-iconbtn" title="Alternar tema" onClick={()=>setTheme(theme==='dark'?'light':'dark')}>{theme==='dark'?<Sun size={18}/>:<Moon size={18}/>}</button><button className="sos-iconbtn" title="Atividades" onClick={()=>select('operations')}><Bell size={17}/>{activity.length>0&&<i/>}</button><div className="sos-top-avatar">{first(account.name||'US')}</div></div></header>
      <div className="sos-context"><div className="sos-select-wrap"><Building2 size={15}/><select id="sos-workspace" value={wid} onChange={e=>setWid(e.target.value)}><option value="">Escolha uma empresa</option>{workspaces.map(w=><option key={w.id} value={w.id}>{w.name}</option>)}</select><ChevronsUpDown size={15}/></div><span className="sos-context-line"/><span className="sos-context-label"><CircleDot size={13}/> {ws?'Ambiente '+(role==='owner'?'proprietário':'compartilhado · '+role):'Aguardando configuração'}</span><div className="sos-context-spacer"/><button className="sos-context-new" onClick={()=>open('company')}><Plus size={15}/> Nova empresa</button></div>
      <main className="sos-main"><div className="sos-pagehead"><div><div className="sos-overline">R2R SALESOS <span>/</span> {ws?.name?.toUpperCase()||'CONFIGURAÇÃO'}</div><h1>{title}</h1><p>{({overview:'Uma visão clara do que acontece no seu comercial.',operations:'Controle de atividades, campanhas e decisões dos agentes.',contacts:'Contatos unificados com dados, origem e permissões.',inbox:'Cada interação com contexto e rastreabilidade.',pipeline:'Oportunidades organizadas por etapa comercial.',campaigns:'Abordagens e cadências adaptadas aos seus nichos.',calendar:'Compromissos, tarefas e disponibilidade comercial.',agents:'Defina papéis, limites e diretrizes de inteligência artificial.',knowledge:'Informações verificadas para orientar sua operação.',intelligence:'Analise sua estratégia e prepare abordagens mais relevantes.',reports:'Indicadores registrados, sem números fictícios.',wallet:'Saldo e recargas de teste com trilha financeira.',integrations:'Estado de conexão dos seus provedores.',team:'Acesso e colaboração com permissões por empresa.',settings:'Políticas de segurança e limites da operação.'} as R)[page]}</p></div><div className="sos-head-actions">{actions.map(a=><button key={a.name} className={'sos-btn '+(a.secondary?'secondary':'primary')} disabled={!editable&&!a.secondary} onClick={a.act}><a.icon size={16}/>{a.name}</button>)}</div></div>
      {!ws?<div className="sos-onboarding"><div><Building2 size={29}/><h2>Configure sua primeira empresa</h2><p>Crie uma operação para organizar seus contatos, ofertas, agentes e campanhas sem misturar dados entre nichos.</p><button className="sos-btn primary" onClick={()=>open('company')}><Plus size={16}/> Criar empresa</button></div></div>:<>
      {page==='overview'&&<>
        <div className="sos-overview-strip"><div className="sos-strip-head"><span><span className="sos-live-dot"/> PAINEL COMERCIAL</span><span>{date(data.generatedAt)} · Dados registrados</span></div><div className="sos-strip-body"><div><h2>Seu comercial, sob controle.</h2><p>Uma visão integrada de contatos, conversas e oportunidades.</p></div><button onClick={()=>select('operations')}>Abrir central de operações <ArrowUpRight size={16}/></button></div></div>
        <div className="sos-kpi-grid"><Kpi icon={UsersRound} label="Contatos cadastrados" value={fmtNum(stats.total)} foot="Nesta empresa"/><Kpi icon={BadgeCheck} label="Leads qualificados" value={fmtNum(stats.qualified)} foot="Pipeline comercial" tone="green"/><Kpi icon={CalendarCheck2} label="Reuniões agendadas" value={fmtNum(stats.booked)} foot="Compromissos ativos" tone="violet"/><Kpi icon={Target} label="Oportunidades convertidas" value={fmtNum(stats.converted)} foot="Etapa: convertido" tone="amber"/></div>
        <div className="sos-two-col"><div className="sos-panel"><div className="sos-panel-head"><div><h3>Funil comercial</h3><p>Contatos por estágio do pipeline</p></div><button onClick={()=>select('pipeline')}>Ver pipeline <ArrowUpRight size={15}/></button></div><div className="sos-funnel">{['Novo Lead','Em Prospecção','Interesse Identificado','Lead Qualificado','Negociação','Convertido'].map((s,i)=>{const n=leads.filter(l=>(l.stage||l.status||'Novo Lead')===s).length;return <div className="sos-funnel-row" key={s}><span>{s}</span><div className="sos-funnel-track"><i style={{width:(stats.total?Math.max(2,n/stats.total*100):0)+'%'}} className={'sos-bar-'+i}/></div><b>{n}</b></div>;})}</div><div className="sos-subnote"><CircleHelp size={14}/> Exibe dados cadastrados; sem conversões estimadas.</div></div><div className="sos-panel"><div className="sos-panel-head"><div><h3>Atividades recentes</h3><p>Trilha de auditoria da operação</p></div><Activity size={17}/></div>{activity.length?<div className="sos-event-list">{activity.slice(0,6).map(a=><div className="sos-event" key={a.id}><span><CircleDot size={13}/></span><div><b>{a.title}</b><small>{datetime(a.at)}</small></div></div>)}</div>:<Placeholder icon={Clock3} title="Tudo pronto para começar" description="Seus eventos aparecem aqui conforme as operações são registradas."/>}</div></div>
        <div className="sos-quickhead"><h3>Acesso rápido</h3><small>Aplicações da sua operação</small></div><div className="sos-shortcuts">{[{p:'contacts',t:'Contatos & Empresas',d:'Organize e qualifique',icon:UsersRound},{p:'campaigns',t:'Criar campanhas',d:'Canais e cadências',icon:GitBranch},{p:'agents',t:'Agentes de IA',d:'Perfis e regras',icon:Bot},{p:'calendar',t:'Agenda Inteligente',d:'Reuniões e tarefas',icon:CalendarDays}].map(s=><button className="sos-shortcut" key={s.p} onClick={()=>select(s.p)}><s.icon size={20}/><span><b>{s.t}</b><small>{s.d}</small></span><ArrowUpRight size={16}/></button>)}</div>
      </>}
      {page==='operations'&&<><div className="sos-kpi-grid"><Kpi icon={GitBranch} label="Campanhas ativas" value={String(stats.active)} foot="Status do orquestrador"/><Kpi icon={Send} label="Solicitações aceitas" value={String(stats.initiated)} foot="Aceites n8n, não entregas" tone="green"/><Kpi icon={PhoneCall} label="Eventos de chamadas" value={String(stats.calls)} foot="Confirmados por integração" tone="violet"/><Kpi icon={CircleAlert} label="Alertas registrados" value={String(activity.filter(a=>a.kind==='warning').length)} foot="Exigem revisão" tone="amber"/></div><div className="sos-two-col"><div className="sos-panel"><div className="sos-panel-head"><div><h3>Controle de campanhas</h3><p>Pausa de emergência e acompanhamento</p></div><RadioTower size={17}/></div>{campaigns.length?campaigns.map(c=><div className="sos-op-row" key={c.id}><div className="sos-square"><GitBranch size={16}/></div><div><b>{c.name}</b><small>Até {c.dailyLimit} tentativas/dia · {c.channels?.join(', ')}</small></div><Status value={c.status}/>{c.status==='active'&&<button className="sos-btn danger tiny" onClick={()=>stopCampaign(c,'pause')}><Pause size={13}/> Pausar</button>}</div>):<Placeholder icon={GitBranch} title="Sem campanhas" description="Crie sua primeira campanha com regras e canais permitidos."/>}</div><div className="sos-panel"><div className="sos-panel-head"><div><h3>Fila de eventos</h3><p>Registro cronológico verificado</p></div><button onClick={sync}><RefreshCcw size={16}/></button></div>{activity.length?activity.slice(0,12).map(a=><div key={a.id} className="sos-op-row"><div className="sos-square"><Activity size={15}/></div><div><b>{a.title}</b><small>{datetime(a.at)}</small></div></div>):<Placeholder icon={Activity} title="Nenhum evento recente" description="A central não inventa chamadas ou mensagens em andamento."/>}</div></div><div className="sos-info-line"><ShieldCheck size={16}/> Atualização manual disponível. A fila externa, concorrência real e status de agentes requerem eventos do provedor.</div></>}
      {page==='contacts'&&<div className="sos-panel flush"><div className="sos-panel-head spaced"><div><h3>Base de contatos</h3><p>{filteredLeads.length} contato(s) · supressão compartilhada entre canais</p></div><div className="sos-inline-actions"><label className="sos-btn secondary sos-file-btn"><FileUp size={15}/> Importar CSV <input type="file" accept=".csv,text/csv" onChange={e=>e.target.files?.[0]&&uploadCsv(e.target.files[0])}/></label></div></div><div className="sos-tablewrap"><table className="sos-table"><thead><tr><th>CONTATO</th><th>EMPRESA</th><th>TELEFONE / EMAIL</th><th>ORIGEM</th><th>ETAPA</th><th>PRIVACIDADE</th><th>AÇÕES</th></tr></thead><tbody>{filteredLeads.map(l=><tr key={l.id}><td><button className="sos-person" onClick={()=>{setSelectedLead(l.id);select('inbox');}}><span>{first(l.name)}</span><b>{l.name}</b></button></td><td>{l.company||'—'}</td><td><div className="sos-stack"><b>{l.phone||'—'}</b><small>{l.email||'—'}</small></div></td><td><small>{l.source||'Não informada'}</small></td><td><Status value={l.stage||l.status||'Novo Lead'}/></td><td>{l.optOut?<Status value="bloqueado"/>:<span className="sos-verified"><ShieldCheck size={13}/> Registrado</span>}</td><td><button className="sos-action" onClick={()=>{setSelectedLead(l.id);select('inbox');}}><Eye size={15}/> Abrir</button>{!l.optOut&&editable&&<button className="sos-action danger-text" onClick={()=>blockLead(l)}><Ban size={14}/></button>}</td></tr>)}</tbody></table>{!filteredLeads.length&&<Placeholder icon={UsersRound} title="Nenhum contato neste filtro" description="Importe um CSV ou cadastre contatos com origem e base legal documentadas."/>}</div></div>}
      {page==='inbox'&&<div className="sos-inbox"><div className="sos-inbox-list"><div className="sos-inbox-title"><b>Conversas</b><small>{leads.length} contatos</small></div>{leads.length?leads.filter(l=>l.name?.toLowerCase().includes(search.toLowerCase())).map(l=><button key={l.id} className={'sos-inbox-contact '+(selectedLead===l.id?'on':'')} onClick={()=>setSelectedLead(l.id)}><span className="sos-profile">{first(l.name)}</span><div><b>{l.name}</b><small>{l.company||l.email||'Sem empresa'}</small></div><ChevronRight size={15}/></button>):<Placeholder icon={MessagesSquare} title="Sem contatos" description="Cadastre contatos para consultar seus históricos."/>}</div><div className="sos-inbox-thread">{(()=>{const lead=leads.find(l=>l.id===selectedLead)||leads[0];const history=messages.filter(m=>m.leadId===lead?.id);return lead?<><div className="sos-thread-head"><span className="sos-profile">{first(lead.name)}</span><div><b>{lead.name}</b><small>{lead.company||'Contato comercial'}</small></div><Status value={lead.stage||lead.status||'Novo Lead'}/></div><div className="sos-thread-scroll">{history.length?history.map(m=><div className={'sos-bubble '+(m.direction==='inbound'?'incoming':m.channel==='internal'?'internal':'outgoing')} key={m.id}><div><span>{labels[m.channel]||m.channel}</span><Status value={m.status}/></div><p>{m.message||'Evento registrado sem conteúdo de mensagem.'}</p><small>{datetime(m.at)}</small></div>):<Placeholder icon={MessageCircle} title="Ainda não há conversas" description="Mensagens somente aparecem após registro interno ou eventos recebidos de provedores."/>}</div><div className="sos-thread-compose"><p><LockKeyhole size={14}/> Notas internas não são enviadas ao cliente.</p><button className="sos-btn secondary" disabled={!editable} onClick={()=>{setSelectedLead(lead.id);open('note');}}><Pencil size={15}/> Registrar nota interna</button></div></>:<Placeholder icon={MessagesSquare} title="Selecione um contato" description="Histórico de e-mail, WhatsApp, voz, notas e eventos."/>;})()}</div><div className="sos-inbox-aside">{(()=>{const l=leads.find(x=>x.id===selectedLead)||leads[0];return l?<><div className="sos-about-user"><div className="sos-profile bigger">{first(l.name)}</div><b>{l.name}</b><small>{l.company||'Contato'}</small></div><div className="sos-side-detail"><span>E-mail</span><b>{l.email||'—'}</b><span>Telefone</span><b>{l.phone||'—'}</b><span>Etapa do pipeline</span><Status value={l.stage||l.status||'Novo Lead'}/><span>Origem</span><b>{l.source||'—'}</b><span>Base legal</span><b>{l.legalBasis||'—'}</b><span>WhatsApp opt-in</span><b>{l.whatsappOptIn?'Sim':'Não documentado'}</b></div>{!l.optOut&&editable&&<button className="sos-btn danger full" onClick={()=>blockLead(l)}><Ban size={15}/> Bloquear contatos</button>}</>:null;})()}</div></div>}
      {page==='pipeline'&&<><div className="sos-pipeline-stats"><span><Target size={16}/> {leads.length} contatos no funil</span><span><Coins size={16}/> Potencial: {money(opportunities.reduce((a,v)=>a+(Number(v.value)||0),0))}</span><span><TrendingUp size={16}/> {stats.converted} convertido(s)</span></div><div className="sos-kanban">{cols.map(stage=><div key={stage} className="sos-stage" onDragOver={e=>e.preventDefault()} onDrop={async e=>{e.preventDefault();const lead=leads.find(l=>l.id===e.dataTransfer.getData('lead-id'));if(lead&&editable)await changeStage(lead,stage);}}><div className="sos-stage-head"><div><span className="sos-stage-color"/><b>{stage}</b></div><em>{leads.filter(l=>!l.optOut&&(l.stage||l.status||'Novo Lead')===stage).length}</em></div><div className="sos-stage-cards">{leads.filter(l=>!l.optOut&&(l.stage||l.status||'Novo Lead')===stage).map(l=><div key={l.id} className="sos-leadcard" draggable={editable} onDragStart={e=>e.dataTransfer.setData('lead-id',l.id)}><div><GripVertical size={14}/><b>{l.name}</b></div><small>{l.company||'Contato independente'}</small><div className="sos-leadcard-bottom"><span><PhoneCall size={12}/> {l.phone?'Telefone':'Sem telefone'}</span><select aria-label={'Alterar etapa de '+l.name} value={stage} disabled={!editable} onChange={e=>changeStage(l,e.target.value)}>{cols.map(s=><option key={s}>{s}</option>)}</select></div></div>)}</div></div>)}</div></>}
      {page==='campaigns'&&<><div className="sos-tabs-line"><b>Campanhas</b><button onClick={()=>open('cadence')} disabled={!editable}><Plus size={14}/> Nova cadência</button></div><div className="sos-cardgrid">{campaigns.length?campaigns.map(c=><div className="sos-card" key={c.id}><div className="sos-card-head"><span className="sos-card-icon"><GitBranch size={18}/></span><Status value={c.status}/></div><h3>{c.name}</h3><p>{c.objective||'Campanha sem objetivo detalhado.'}</p><div className="sos-chips">{c.channels?.map((ch:string)=><span key={ch}>{labels[ch]}</span>)}</div><div className="sos-card-foot"><small><Clock3 size={14}/> Limite: {c.dailyLimit}/dia</small>{c.status==='active'?<button className="sos-btn danger tiny" onClick={()=>stopCampaign(c,'pause')}><Pause size={14}/> Pausar</button>:<button disabled={!admin} className="sos-btn secondary tiny" onClick={()=>stopCampaign(c,'activate')}><Play size={14}/> Ativar</button>}</div></div>):<Placeholder icon={GitBranch} title="Ainda não existem campanhas" description="Crie uma campanha com e-mail, WhatsApp ou ligações de IA." action={<button className="sos-btn primary" onClick={()=>open('campaign')}>Criar campanha</button>}/>}</div><div className="sos-quickhead"><h3>Cadências preparadas</h3><small>Execução automática em desenvolvimento · não ativa</small></div><div className="sos-cadences">{filtered('cadences').length?filtered('cadences').map(c=><div className="sos-op-row" key={c.id}><div className="sos-square"><GitBranch size={16}/></div><div><b>{c.title}</b><small>{c.steps?.length||0} etapas definidas · somente planejamento</small></div><Status value={c.status}/></div>):<Placeholder icon={ListChecks} title="Nenhuma cadência" description="Configure etapas e condições antes da homologação do motor de execução."/>}</div></>}
      {page==='calendar'&&<><div className="sos-calendar-tools"><div className="sos-calendar-month"><button className="sos-iconbtn" onClick={()=>setCalendarAt(new Date(calendarAt.getFullYear(),calendarAt.getMonth()+(calendarMode==='month'?-1:0),calendarAt.getDate()+(calendarMode==='month'?0:calendarMode==='week'?-7:-1)))}><ChevronRight className="sos-flip" size={16}/></button><strong>{calendarAt.toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</strong><button className="sos-iconbtn" onClick={()=>setCalendarAt(new Date(calendarAt.getFullYear(),calendarAt.getMonth()+(calendarMode==='month'?1:0),calendarAt.getDate()+(calendarMode==='month'?0:calendarMode==='week'?7:1)))}><ChevronRight size={16}/></button></div><div className="sos-segmented">{(['day','week','month'] as const).map(m=><button className={calendarMode===m?'active':''} key={m} onClick={()=>setCalendarMode(m)}>{({day:'Dia',week:'Semana',month:'Mês'} as R)[m]}</button>)}</div></div><div className="sos-calendar-panel"><div className="sos-calendar-grid">{Array.from({length:calendarMode==='day'?1:calendarMode==='week'?7:new Date(calendarAt.getFullYear(),calendarAt.getMonth()+1,0).getDate()},(_,i)=>{const d=calendarMode==='day'?calendarAt:calendarMode==='week'?new Date(calendarAt.getFullYear(),calendarAt.getMonth(),calendarAt.getDate()-calendarAt.getDay()+i):new Date(calendarAt.getFullYear(),calendarAt.getMonth(),i+1);const ev=appointments.filter(a=>new Date(a.startAt).toDateString()===d.toDateString());return <div className="sos-day" key={i}><div className="sos-day-label">{d.toLocaleDateString('pt-BR',{weekday:'short'})}<b>{d.getDate()}</b></div>{ev.map(a=><div className="sos-day-event" key={a.id}><b>{a.title}</b><small>{datetime(a.startAt).split(' ')[1]||''} · {a.duration} min</small></div>)}</div>;})}</div></div><div className="sos-quickhead"><h3>Próximos compromissos</h3><small>Agenda interna · Google Calendar não conectado</small></div><div className="sos-panel">{appointments.length?appointments.map(a=><div key={a.id} className="sos-op-row"><div className="sos-square"><CalendarClock size={17}/></div><div><b>{a.title}</b><small>{datetime(a.startAt)} · {a.duration} minutos · {a.assignee||'Sem responsável'}</small></div><Status value={a.status}/>{editable&&<button className="sos-btn danger tiny" onClick={()=>cancelMeeting(a)}>Cancelar</button>}</div>):<Placeholder icon={CalendarDays} title="Agenda livre" description="Agende reuniões e retornos; o sistema reserva os horários para evitar colisões."/>}</div></>}
      {page==='agents'&&<><div className="sos-info-line"><ShieldCheck size={16}/> Perfis de agente são armazenados por empresa. Execução autônoma exige integrações e homologação; os perfis começam desativados.</div><div className="sos-cardgrid">{filtered('agents').length?filtered('agents').map(a=><div className="sos-card" key={a.id}><div className="sos-card-head"><span className="sos-card-icon"><Bot size={19}/></span><Status value={a.enabled?'active':'draft'}/></div><h3>{a.name}</h3><p>{a.role||'Assistente comercial personalizado'}</p><div className="sos-mini-details"><div><span>Tom de voz</span><b>{a.tone||'Profissional'}</b></div><div><span>Região</span><b>{a.region||'Brasil'}</b></div></div><div className="sos-card-foot"><small>Configuração salva</small><button className="sos-btn secondary tiny" disabled={!editable} onClick={()=>open('agentEdit',a)}><Pencil size={14}/> Editar</button></div></div>):<Placeholder icon={Bot} title="Sua equipe de IA começa aqui" description="Defina identidade, missão, tom e limites para cada agente de vendas." action={<button className="sos-btn primary" onClick={()=>open('agent')}>Criar agente</button>}/>}</div></>}
      {page==='knowledge'&&<><div className="sos-knowledge-toolbar"><div><b>Fontes autorizadas</b><small>Textos e arquivos separados por empresa</small></div><label className="sos-btn secondary sos-file-btn"><FileUp size={15}/> Enviar PDF / texto <input type="file" accept=".pdf,.txt,.md" onChange={e=>e.target.files?.[0]&&fileUpload(e.target.files[0])}/></label></div><div className="sos-cardgrid">{filtered('knowledge').length?filtered('knowledge').map(a=><div className="sos-card" key={a.id}><div className="sos-card-head"><span className="sos-card-icon"><FileText size={18}/></span><span className="sos-muted">{a.mime?'Arquivo':'Texto'}</span></div><h3>{a.title}</h3><p>{a.content?.slice(0,175)||a.description||'Arquivo armazenado'}</p><div className="sos-card-foot"><small>{date(a.createdAt)}</small>{a.storagePath?<button className="sos-btn secondary tiny" onClick={()=>showFile(a)}><ExternalLink size={13}/> Abrir</button>:<span className="sos-verified"><Check size={14}/> Texto indexável</span>}</div></div>):<Placeholder icon={BookOpenText} title="Base de conhecimento vazia" description="Cadastre preços, produtos e políticas verificadas para orientar os agentes."/>}</div><div className="sos-info-line"><CircleHelp size={16}/> Arquivos armazenados não são automaticamente indexados. Para geração fundamentada, cadastre conhecimento textual no editor.</div></>}
      {page==='intelligence'&&<div className="sos-two-col intelligence"><div className="sos-panel"><div className="sos-panel-head"><div><h3>Studio de abordagens com IA</h3><p>Rascunhos contextualizados por nicho e fonte autorizada</p></div><Sparkles size={19}/></div><div className="sos-form-stack"><Field title="Canal"><select value={form.channel||'email'} onChange={e=>f('channel',e.target.value)}><option value="email">E-mail</option><option value="whatsapp">WhatsApp</option><option value="voice">Ligação IA</option></select></Field><Field title="Objetivo da abordagem"><input value={form.objective||''} onChange={e=>f('objective',e.target.value)} placeholder="Ex.: Apresentar serviços de marketing digital"/></Field><Field title="Oferta comercial verificada"><textarea rows={4} value={form.offer||''} onChange={e=>f('offer',e.target.value)} placeholder="Descreva somente informações que sua empresa realmente oferece."/></Field><button className="sos-btn primary" disabled={busy||!editable} onClick={makeDraft}><Sparkles size={16}/> {busy?'Gerando...':'Gerar rascunho com IA'}</button></div></div><div className="sos-panel"><div className="sos-panel-head"><div><h3>Prévia do conteúdo</h3><p>Revisão humana obrigatória antes de utilizar</p></div><FileText size={18}/></div>{draft?<div className="sos-ai-output"><span>RASCUNHO · NÃO ENVIADO</span><p>{draft}</p><button className="sos-btn secondary" onClick={()=>navigator.clipboard.writeText(draft).then(()=>show('Conteúdo copiado.'))}><Copy size={15}/> Copiar texto</button></div>:<Placeholder icon={BrainCircuit} title="Rascunho aguardando contexto" description="Informe oferta e objetivo. A IA utilizará dados informados e conhecimento textual desta empresa."/>}</div></div>}
      {page==='reports'&&<><div className="sos-report-head"><span>Período dos eventos</span><select value={reportPeriod} onChange={e=>setReportPeriod(e.target.value)}><option value="7">Últimos 7 dias</option><option value="30">Últimos 30 dias</option><option value="90">Últimos 90 dias</option></select></div><div className="sos-kpi-grid"><Kpi icon={MessageCircle} label="Respostas confirmadas" value={String(stats.inbound)} foot="Webhook ou provedor"/><Kpi icon={CheckCircle2} label="Entregas confirmadas" value={String(stats.delivered)} foot="Não inclui aceite inicial" tone="green"/><Kpi icon={PhoneCall} label="Eventos telefônicos" value={String(stats.calls)} foot="Voz / ciclo registrado" tone="violet"/><Kpi icon={Coins} label="Custo reportado" value={money(stats.cost)} foot="Eventos recebidos, pode ser parcial" tone="amber"/></div><div className="sos-two-col"><div className="sos-panel"><div className="sos-panel-head"><h3>Resultados por canal</h3></div>{['email','whatsapp','voice'].map(ch=>{const n=messages.filter(m=>m.channel===ch).length;return <div className="sos-funnel-row" key={ch}><span>{labels[ch]}</span><div className="sos-funnel-track"><i style={{width:(messages.length?Math.max(2,n/messages.length*100):0)+'%'}}/></div><b>{n}</b></div>;})}<div className="sos-subnote">Os eventos só são contabilizados quando recebidos no backend.</div></div><div className="sos-panel"><div className="sos-panel-head"><h3>Taxa de qualificação</h3></div><div className="sos-rate"><strong>{stats.total?((stats.qualified/stats.total)*100).toFixed(1)+'%':'—'}</strong><p>{stats.qualified} leads qualificados / {stats.total} contatos</p></div><div className="sos-subnote">Custo por reunião será disponível após integração dos custos e resultados confirmados.</div></div></div></>}
      {page==='wallet'&&<><div className="sos-wallet-head"><div className="sos-wallet-card"><div><span>CARTEIRA DE TESTES · SANDBOX</span><Wallet size={21}/></div><p>Saldo confirmado de teste</p><h2>{money((wallet.balanceCents||0)/100)}</h2><small>Sem valor financeiro real, não habilita automaticamente provedores externos.</small></div><div className="sos-wallet-details"><div><span>Créditos reservados</span><strong>{money((wallet.reservedCents||0)/100)}</strong></div><div><span>Recargas registradas</span><strong>{topups.length}</strong></div><div><span>Créditos confirmados</span><strong>{ledger.filter(l=>l.deltaCents>0).length}</strong></div><button className="sos-btn primary" disabled={!admin} onClick={()=>open('topup')}><CreditCard size={16}/> Fazer recarga de teste</button></div></div><div className="sos-panel"><div className="sos-panel-head"><div><h3>Extrato e recargas</h3><p>Lançamentos confirmados e cobranças pendentes</p></div></div><div className="sos-tablewrap"><table className="sos-table"><thead><tr><th>DATA</th><th>TIPO</th><th>VALOR</th><th>STATUS</th></tr></thead><tbody>{[...ledger,...topups].sort((a,b)=>String(b.at||b.createdAt).localeCompare(String(a.at||a.createdAt))).map(t=><tr key={t.id}><td>{date(t.at||t.createdAt)}</td><td>{t.kind||'Recarga sandbox'}</td><td>{money((t.amountCents||t.deltaCents||0)/100)}</td><td><Status value={t.status||'confirmed'}/></td></tr>)}</tbody></table>{!ledger.length&&!topups.length&&<Placeholder icon={Wallet} title="Nenhuma recarga" description="Use o Asaas sandbox para verificar cobranças sem movimentar dinheiro real."/>}</div></div></>}
      {page==='integrations'&&<><div className="sos-info-line"><ShieldCheck size={16}/> Credencial presente não significa integração validada. Envio real segue desativado enquanto faltarem testes e aprovações.</div><div className="sos-cardgrid integration-grid">{(integrations.length?integrations:[{key:'n8n',name:'n8n',configured:data.integrations?.n8n},{key:'meta',name:'WhatsApp Cloud API',configured:data.integrations?.meta},{key:'email',name:'E-mail SMTP/API',configured:data.integrations?.email},{key:'vapi',name:'Vapi Voz IA',configured:data.integrations?.vapi},{key:'asaas',name:'Asaas Sandbox',configured:data.integrations?.asaasSandbox},{key:'calendar',name:'Google Calendar',configured:false}]).map(i=><div className="sos-card" key={i.key}><div className="sos-card-head"><span className="sos-card-icon"><Cable size={19}/></span><Status value={i.configured?'pending':'draft'}/></div><h3>{i.name}</h3><p>{i.configured?'Credencial cadastrada; autenticação e funcionalidade não homologadas.':'Aguardando credenciais, OAuth ou serviço habilitado.'}</p><div className="sos-card-foot"><small>{i.configured?'Configuração parcial':'Não conectado'}</small>{['vapi','meta','asaas'].includes(i.key)?<button className="sos-btn secondary tiny" disabled={!i.configured||!admin||busy} onClick={()=>testIntegration(i.key)}>Testar acesso</button>:<span className="sos-muted">Teste externo pendente</span>}</div></div>)}</div><button className="sos-btn secondary" onClick={async()=>{try{const r=await api.get('/api/salesos/integrations');setIntegrations(r.data);show('Estado atualizado; nenhuma cobrança ou chamada de teste foi iniciada.');}catch(e){show(getErr(e));}}}><RefreshCcw size={15}/> Atualizar status técnico</button></>}
      {page==='team'&&<><div className="sos-panel"><div className="sos-panel-head"><div><h3>Membros da empresa</h3><p>Permissões: proprietário, administrador, editor e visualizador</p></div><UserRoundCog size={19}/></div><div className="sos-op-row"><div className="sos-person-portrait">{first(account.name||account.email||'Titular')}</div><div><b>{account.name||'Conta conectada'}</b><small>{account.email||'Autenticado'} · Papel atual</small></div><Status value={role}/></div>{filtered('team').map(t=><div key={t.id} className="sos-op-row"><div className="sos-person-portrait">{first(t.name||t.email)}</div><div><b>{t.name||t.email}</b><small>{t.email}</small></div><Status value={t.role}/></div>)}</div><div className="sos-info-line"><ShieldCheck size={16}/> Convites exigem conta autenticada, e-mail permitido e aceite explícito. A integração de credenciais externas por empresa permanece separada da gestão de membros.</div></>}
      {page==='settings'&&<div className="sos-two-col"><div className="sos-panel"><div className="sos-panel-head"><div><h3>Governança de prospecção</h3><p>Políticas ativas de segurança</p></div><ShieldCheck size={19}/></div>{['Origem e base legal documentadas','WhatsApp com opt-in específico','Permissão verificada para voz','Oposição bloqueia novos contatos','Controle de duplicidades por campanha/canal','Horário inicial: seg–sex, 09h–18h','Limite planejado: 500 tentativas/dia','Envios pendentes de homologação externa'].map(t=><div className="sos-setting" key={t}><CheckCircle2 size={16}/>{t}</div>)}</div><div className="sos-panel"><div className="sos-panel-head"><div><h3>Ambiente e implantação</h3><p>Informações de sistema</p></div><Settings2 size={19}/></div><div className="sos-setting"><span>Nome</span><strong>R2R SalesOS</strong></div><div className="sos-setting"><span>Função</span><strong>{role}</strong></div><div className="sos-setting"><span>Fuso</span><strong>America/Sao_Paulo</strong></div><div className="sos-setting"><span>Versão</span><strong>Beta operacional</strong></div><div className="sos-setting"><span>Integrações ativas</span><strong>Não homologadas</strong></div><div className="sos-subnote">O aplicativo anterior e seus workflows existentes foram preservados. Os serviços Vapi, Meta, Calendar e Asaas precisam de testes reais autorizados.</div><button className="sos-btn secondary" onClick={()=>window.location.hash='legacy'}><ExternalLink size={15}/> Abrir interface legada (preservada)</button></div></div>}
      </>}
      <div className="sos-footer"><span>R2R SalesOS © 2026 · Plataforma de inteligência comercial</span><span><LockKeyhole size={13}/> Dados isolados por operação · Ações auditáveis</span></div></main>
    </div>
    {notice&&<div className="sos-toast"><CircleAlert size={16}/><span>{notice}</span><button onClick={()=>setNotice('')}><X size={15}/></button></div>}
    {modal&&<Modal title={({company:'Nova empresa / nicho',lead:'Novo contato',campaign:'Nova campanha',agent:'Configurar agente de IA',agentEdit:'Editar agente de IA',knowledge:'Adicionar conhecimento',task:'Nova tarefa',opportunity:'Nova oportunidade',cadence:'Nova cadência',meeting:'Novo compromisso',note:'Nota de atendimento',topup:'Recarga de créditos — sandbox',invite:'Convidar membro'} as R)[modal]} onClose={()=>setModal('')} footer={<><button className="sos-btn secondary" onClick={()=>setModal('')}>Cancelar</button><button className="sos-btn primary" onClick={handleForm} disabled={busy}>{busy?'Processando...':'Confirmar e salvar'} <ArrowRight size={15}/></button></>}>
      {modal==='company'&&<><Field title="Nome da empresa"><input required value={form.name||''} onChange={e=>f('name',e.target.value)} placeholder="Ex.: R2R Marketing Digital"/></Field><Field title="Nicho de atuação"><input value={form.niche||''} onChange={e=>f('niche',e.target.value)} placeholder="Ex.: Marketing digital, imobiliário, indústria"/></Field><Field title="Descrição e proposta"><textarea rows={3} value={form.description||''} onChange={e=>f('description',e.target.value)}/></Field></>}
      {modal==='lead'&&<><div className="sos-two-fields"><Field title="Nome do contato"><input value={form.name||''} onChange={e=>f('name',e.target.value)}/></Field><Field title="Empresa"><input value={form.company||''} onChange={e=>f('company',e.target.value)}/></Field></div><div className="sos-two-fields"><Field title="E-mail"><input type="email" value={form.email||''} onChange={e=>f('email',e.target.value)}/></Field><Field title="Telefone (DDD)"><input value={form.phone||''} onChange={e=>f('phone',e.target.value)}/></Field></div><Field title="Origem documentada"><input value={form.source||''} onChange={e=>f('source',e.target.value)} placeholder="Ex.: formulário de cadastro"/></Field><Field title="Base legal"><select value={form.legalBasis||''} onChange={e=>f('legalBasis',e.target.value)}><option value="">Selecione</option><option value="consent">Consentimento</option><option value="legitimate_interest_assessed">Legítimo interesse avaliado</option><option value="contractual">Contratual aplicável</option></select></Field><label className="sos-check"><input type="checkbox" checked={form.whatsappOptIn===true} onChange={e=>f('whatsappOptIn',e.target.checked)}/> WhatsApp opt-in comprovado</label><label className="sos-check"><input type="checkbox" checked={form.voiceAllowed===true} onChange={e=>f('voiceAllowed',e.target.checked)}/> Ligação comercial autorizada</label><p className="sos-note">Marcar permissões não cria consentimento. Guarde evidências válidas.</p></>}
      {modal==='campaign'&&<><Field title="Nome da campanha"><input value={form.name||''} onChange={e=>f('name',e.target.value)}/></Field><Field title="Objetivo comercial"><textarea rows={2} value={form.objective||''} onChange={e=>f('objective',e.target.value)}/></Field><div className="sos-checkline">{['email','whatsapp','voice'].map(ch=><label className="sos-check" key={ch}><input type="checkbox" checked={(form.channels||[]).includes(ch)} onChange={e=>f('channels',e.target.checked?[...(form.channels||[]),ch]:(form.channels||[]).filter((x:string)=>x!==ch))}/>{labels[ch]}</label>)}</div><Field title="Máximo por dia"><input type="number" min="1" max="500" value={form.dailyLimit||50} onChange={e=>f('dailyLimit',e.target.value)}/></Field><Field title="Mensagem e-mail"><textarea rows={2} value={form.emailText||''} onChange={e=>f('emailText',e.target.value)}/></Field><Field title="Template WhatsApp aprovado (nome exato)"><input value={form.whatsappTemplateName||''} onChange={e=>f('whatsappTemplateName',e.target.value)}/></Field><Field title="Mensagem WhatsApp"><textarea rows={2} value={form.whatsappText||''} onChange={e=>f('whatsappText',e.target.value)}/></Field><Field title="Roteiro de voz da IA"><textarea rows={3} value={form.voiceScript||''} onChange={e=>f('voiceScript',e.target.value)}/></Field><p className="sos-note">Campanha é criada em rascunho. Não gera disparos ao salvar.</p></>}
      {['agent','agentEdit'].includes(modal)&&<><Field title="Nome do agente"><input value={form.name||''} onChange={e=>f('name',e.target.value)} placeholder="Ex.: SDR Imobiliário"/></Field><Field title="Papel e objetivo"><input value={form.role||''} onChange={e=>f('role',e.target.value)}/></Field><div className="sos-two-fields"><Field title="Tom de voz"><select value={form.tone||'Profissional'} onChange={e=>f('tone',e.target.value)}><option>Profissional</option><option>Consultivo</option><option>Objetivo</option><option>Empático</option></select></Field><Field title="Região"><input value={form.region||''} onChange={e=>f('region',e.target.value)} placeholder="Brasil"/></Field></div><Field title="Instruções e limites"><textarea rows={6} value={form.instructions||''} onChange={e=>f('instructions',e.target.value)} placeholder="Informe preço apenas se estiver na base, respeite opt-out, encaminhe oportunidades..."/></Field></>}
      {modal==='knowledge'&&<><Field title="Título"><input value={form.title||''} onChange={e=>f('title',e.target.value)}/></Field><Field title="Conteúdo comercial verificado"><textarea rows={9} value={form.content||''} onChange={e=>f('content',e.target.value)} placeholder="Preços, serviços, políticas e informações que podem orientar a IA."/></Field></>}
      {modal==='task'&&<><Field title="Tarefa"><input value={form.title||''} onChange={e=>f('title',e.target.value)}/></Field><Field title="Prazo"><input type="datetime-local" value={form.dueAt||''} onChange={e=>f('dueAt',e.target.value)}/></Field><Field title="Responsável"><input value={form.assignee||''} onChange={e=>f('assignee',e.target.value)}/></Field></>}
      {modal==='opportunity'&&<><Field title="Título"><input value={form.title||''} onChange={e=>f('title',e.target.value)}/></Field><Field title="Contato"><select value={form.leadId||''} onChange={e=>f('leadId',e.target.value)}><option value="">Selecione</option>{leads.map(l=><option value={l.id} key={l.id}>{l.name}</option>)}</select></Field><Field title="Valor potencial (R$)"><input type="number" min="0" value={form.value||0} onChange={e=>f('value',Number(e.target.value))}/></Field></>}
      {modal==='cadence'&&<><Field title="Nome da cadência"><input value={form.title||''} onChange={e=>f('title',e.target.value)}/></Field><Field title="Etapas (uma por linha)"><textarea rows={7} value={form.stepsText||''} onChange={e=>f('stepsText',e.target.value)} placeholder={'Validar autorização e base legal\nPrimeiro contato no canal permitido\nAguardar resposta\nQualificar ou encerrar'}/></Field><p className="sos-note">Este editor salva o planejamento; não habilita envios automáticos de cadência.</p></>}
      {modal==='meeting'&&<><Field title="Título do compromisso"><input value={form.title||''} onChange={e=>f('title',e.target.value)}/></Field><Field title="Data e horário"><input type="datetime-local" value={form.startLocal||dateLocal(new Date(Date.now()+86400000))} onChange={e=>f('startLocal',e.target.value)}/></Field><Field title="Duração (min)"><input type="number" min="15" max="240" value={form.duration||60} onChange={e=>f('duration',Number(e.target.value))}/></Field><Field title="Responsável / calendário"><input value={form.assignee||''} onChange={e=>f('assignee',e.target.value)} placeholder="Ex.: Equipe Comercial"/></Field><Field title="Contato relacionado"><select value={form.leadId||''} onChange={e=>f('leadId',e.target.value)}><option value="">Sem contato</option>{leads.map(l=><option key={l.id} value={l.id}>{l.name}</option>)}</select></Field><p className="sos-note">Agenda interna com proteção de conflitos. Google Calendar depende de OAuth, ainda não conectado.</p></>}
      {modal==='note'&&<><Field title="Anotação de atendimento"><textarea rows={8} value={form.message||''} onChange={e=>f('message',e.target.value)} placeholder="Registre o contexto comercial e próximos passos."/></Field><p className="sos-note">Somente uso interno. Nenhuma mensagem será enviada.</p></>}
      {modal==='invite'&&<><Field title="E-mail do convidado"><input type="email" value={form.email||''} onChange={e=>f('email',e.target.value)} placeholder="colaborador@empresa.com.br"/></Field><Field title="Permissão"><select value={form.role||'viewer'} onChange={e=>f('role',e.target.value)}><option value="viewer">Visualizador</option><option value="editor">Editor</option><option value="admin">Administrador</option></select></Field>{inviteLink&&<div className="sos-invite-link"><span>Convite criado: envie o link ao destinatário autorizado.</span><input readOnly value={inviteLink}/><button className="sos-btn secondary" onClick={()=>navigator.clipboard.writeText(inviteLink).then(()=>show('Convite copiado.'))}><Copy size={14}/> Copiar link</button></div>}</>}
      {modal==='topup'&&<><div className="sos-info-line"><CircleAlert size={15}/> Somente ambiente de testes Asaas. Não cria crédito real e não habilita chamadas.</div><div className="sos-topup-options">{[50,100,250,500,1000].map(n=><button key={n} className={'sos-btn '+(Number(form.amount)===n?'primary':'secondary')} onClick={()=>f('amount',n)}>{money(n)}</button>)}</div><Field title="Valor em reais"><input type="number" min="50" max="1000" step="1" value={form.amount||50} onChange={e=>f('amount',Number(e.target.value))}/></Field><p className="sos-note">Cobranças são criadas apenas se as credenciais SANDBOX e cliente Asaas estiverem configurados.</p></>}
    </Modal>}
  </div>;
}
export default App;
